import urllib.request
import json
import base64
import io
import numpy as np
from PIL import Image

URL = "http://loophole-sim:8000/mcp"
HEADERS = {
    "Content-Type": "application/json",
    "Accept": "application/json, text/event-stream",
}


class LoopholeClient:
    def __init__(self, url=URL):
        self.url = url
        self._id = 0
        self.sid = None
        self._init()

    def _post(self, payload):
        h = dict(HEADERS)
        if self.sid:
            h["Mcp-Session-Id"] = self.sid
        req = urllib.request.Request(
            self.url, data=json.dumps(payload).encode(), headers=h, method="POST"
        )
        with urllib.request.urlopen(req, timeout=60) as resp:
            sid = resp.headers.get("Mcp-Session-Id")
            if sid:
                self.sid = sid
            body = resp.read().decode()
            if not body.strip():
                return None
            # Handle SSE or JSON
            if body.startswith("event:") or body.startswith("data:"):
                for line in body.splitlines():
                    if line.startswith("data:"):
                        return json.loads(line[5:].strip())
            return json.loads(body)

    def _init(self):
        self._id += 1
        self._post(
            {
                "jsonrpc": "2.0",
                "id": self._id,
                "method": "initialize",
                "params": {
                    "protocolVersion": "2024-11-05",
                    "capabilities": {},
                    "clientInfo": {"name": "solver", "version": "1.0"},
                },
            }
        )
        self._post({"jsonrpc": "2.0", "method": "notifications/initialized"})

    def list_tools(self):
        self._id += 1
        return self._post({"jsonrpc": "2.0", "id": self._id, "method": "tools/list", "params": {}})

    def call_tool(self, name, arguments=None):
        self._id += 1
        res = self._post(
            {
                "jsonrpc": "2.0",
                "id": self._id,
                "method": "tools/call",
                "params": {"name": name, "arguments": arguments or {}},
            }
        )
        if "error" in res:
            raise RuntimeError(f"MCP error: {res['error']}")
        result = res["result"]
        if result.get("isError"):
            raise RuntimeError(f"Tool error: {result}")
        return result["content"]

    def get_state(self):
        content = self.call_tool("get_state")
        return json.loads(content[0]["text"])

    def get_contacts(self):
        content = self.call_tool("get_contacts")
        return json.loads(content[0]["text"])

    def render(self, **kwargs):
        content = self.call_tool("render", kwargs)
        meta = None
        images = []
        for item in content:
            if item["type"] == "text":
                meta = json.loads(item["text"])
            elif item["type"] == "image":
                raw = base64.b64decode(item["data"])
                img = np.array(Image.open(io.BytesIO(raw)))
                images.append(img)
        return meta, images

