#pragma once
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <algorithm>
#include <vector>
#include <array>
#include <chrono>
#include <omp.h>

struct Vec3 {
    double x, y, z;
    Vec3() : x(0), y(0), z(0) {}
    Vec3(double x_, double y_, double z_) : x(x_), y(y_), z(z_) {}
    Vec3 operator+(const Vec3& o) const { return {x + o.x, y + o.y, z + o.z}; }
    Vec3 operator-(const Vec3& o) const { return {x - o.x, y - o.y, z - o.z}; }
    Vec3 operator*(double s) const { return {x * s, y * s, z * s}; }
    Vec3& operator+=(const Vec3& o) { x += o.x; y += o.y; z += o.z; return *this; }
    double dot(const Vec3& o) const { return x * o.x + y * o.y + z * o.z; }
    Vec3 cross(const Vec3& o) const {
        return {y * o.z - z * o.y, z * o.x - x * o.z, x * o.y - y * o.x};
    }
    double norm2() const { return x * x + y * y + z * z; }
    double norm() const { return std::sqrt(norm2()); }
    Vec3 normalized() const {
        double n = norm();
        return n > 1e-12 ? Vec3{x / n, y / n, z / n} : Vec3{0, 0, 0};
    }
};

struct Quat {
    double w, x, y, z;
    Quat() : w(1), x(0), y(0), z(0) {}
    Quat(double w_, double x_, double y_, double z_) : w(w_), x(x_), y(y_), z(z_) {}
    void normalize() {
        double n = std::sqrt(w * w + x * x + y * y + z * z);
        if (n > 1e-12) { w /= n; x /= n; y /= n; z /= n; }
        if (w < 0) { w = -w; x = -x; y = -y; z = -z; } // canonical hemisphere
    }
    Quat conj() const { return {w, -x, -y, -z}; }
    Quat operator*(const Quat& o) const {
        return {
            w * o.w - x * o.x - y * o.y - z * o.z,
            w * o.x + x * o.w + y * o.z - z * o.y,
            w * o.y - x * o.z + y * o.w + z * o.x,
            w * o.z + x * o.y - y * o.x + z * o.w
        };
    }
    static Quat from_rotvec(const Vec3& rv) {
        double angle = rv.norm();
        if (angle < 1e-10) return Quat(1, 0.5 * rv.x, 0.5 * rv.y, 0.5 * rv.z);
        double s = std::sin(0.5 * angle) / angle;
        Quat q(std::cos(0.5 * angle), rv.x * s, rv.y * s, rv.z * s);
        q.normalize();
        return q;
    }
    Vec3 to_rotvec() const {
        Quat q = *this;
        if (q.w < 0) { q.w = -q.w; q.x = -q.x; q.y = -q.y; q.z = -q.z; }
        double sin_half = std::sqrt(q.x * q.x + q.y * q.y + q.z * q.z);
        if (sin_half < 1e-10) return {2.0 * q.x, 2.0 * q.y, 2.0 * q.z};
        double angle = 2.0 * std::atan2(sin_half, q.w);
        double f = angle / sin_half;
        return {q.x * f, q.y * f, q.z * f};
    }
    double angle_to(const Quat& o) const {
        double d = std::abs(w * o.w + x * o.x + y * o.y + z * o.z);
        if (d > 1.0) d = 1.0;
        return 2.0 * std::acos(d);
    }
    static Quat slerp(const Quat& a, const Quat& b_in, double t) {
        Quat b = b_in;
        double dot = a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z;
        if (dot < 0.0) {
            dot = -dot;
            b = {-b.w, -b.x, -b.y, -b.z};
        }
        if (dot > 0.9995) {
            Quat r(a.w + t * (b.w - a.w), a.x + t * (b.x - a.x),
                   a.y + t * (b.y - a.y), a.z + t * (b.z - a.z));
            r.normalize();
            return r;
        }
        double theta_0 = std::acos(std::min(1.0, dot));
        double theta = theta_0 * t;
        double sin_theta = std::sin(theta);
        double sin_theta_0 = std::sin(theta_0);
        double s0 = std::cos(theta) - dot * sin_theta / sin_theta_0;
        double s1 = sin_theta / sin_theta_0;
        Quat r(s0 * a.w + s1 * b.w, s0 * a.x + s1 * b.x,
               s0 * a.y + s1 * b.y, s0 * a.z + s1 * b.z);
        r.normalize();
        return r;
    }
};

struct Mat3 {
    double m[3][3];
    static Mat3 from_quat(const Quat& q) {
        Mat3 R;
        double xx = q.x * q.x, yy = q.y * q.y, zz = q.z * q.z;
        double xy = q.x * q.y, xz = q.x * q.z, yz = q.y * q.z;
        double wx = q.w * q.x, wy = q.w * q.y, wz = q.w * q.z;
        R.m[0][0] = 1.0 - 2.0 * (yy + zz);
        R.m[0][1] = 2.0 * (xy - wz);
        R.m[0][2] = 2.0 * (xz + wy);
        R.m[1][0] = 2.0 * (xy + wz);
        R.m[1][1] = 1.0 - 2.0 * (xx + zz);
        R.m[1][2] = 2.0 * (yz - wx);
        R.m[2][0] = 2.0 * (xz - wy);
        R.m[2][1] = 2.0 * (yz + wx);
        R.m[2][2] = 1.0 - 2.0 * (xx + yy);
        return R;
    }
    Vec3 operator*(const Vec3& v) const {
        return {
            m[0][0] * v.x + m[0][1] * v.y + m[0][2] * v.z,
            m[1][0] * v.x + m[1][1] * v.y + m[1][2] * v.z,
            m[2][0] * v.x + m[2][1] * v.y + m[2][2] * v.z
        };
    }
    Mat3 operator*(const Mat3& o) const {
        Mat3 R;
        for (int i = 0; i < 3; ++i)
            for (int j = 0; j < 3; ++j)
                R.m[i][j] = m[i][0] * o.m[0][j] + m[i][1] * o.m[1][j] + m[i][2] * o.m[2][j];
        return R;
    }
    Mat3 T() const {
        Mat3 R;
        for (int i = 0; i < 3; ++i)
            for (int j = 0; j < 3; ++j)
                R.m[i][j] = m[j][i];
        return R;
    }
};

struct Pose {
    Vec3 p;
    Quat q;
};

struct Point3f {
    float x, y, z;
};

inline double seg_seg_dist2(const Vec3& p1, const Vec3& q1, const Vec3& p2, const Vec3& q2,
                            Vec3* cp1 = nullptr, Vec3* cp2 = nullptr) {
    Vec3 d1 = q1 - p1;
    Vec3 d2 = q2 - p2;
    Vec3 r = p1 - p2;
    double a = d1.dot(d1);
    double e = d2.dot(d2);
    double f = d2.dot(r);
    double s = 0.0, t = 0.0;
    if (a <= 1e-12 && e <= 1e-12) {
        s = t = 0.0;
    } else if (a <= 1e-12) {
        s = 0.0;
        t = std::clamp(f / e, 0.0, 1.0);
    } else {
        double c = d1.dot(r);
        if (e <= 1e-12) {
            t = 0.0;
            s = std::clamp(-c / a, 0.0, 1.0);
        } else {
            double b = d1.dot(d2);
            double denom = a * e - b * b;
            if (denom != 0.0) s = std::clamp((b * f - c * e) / denom, 0.0, 1.0);
            else s = 0.0;
            t = (b * s + f) / e;
            if (t < 0.0) {
                t = 0.0;
                s = std::clamp(-c / a, 0.0, 1.0);
            } else if (t > 1.0) {
                t = 1.0;
                s = std::clamp((b - c) / a, 0.0, 1.0);
            }
        }
    }
    Vec3 c1 = p1 + d1 * s;
    Vec3 c2 = p2 + d2 * t;
    if (cp1) *cp1 = c1;
    if (cp2) *cp2 = c2;
    return (c1 - c2).norm2();
}

class AlphaModel {
public:
    Mat3 R_ab;
    Vec3 t_ab;
    Vec3 pos0;
    Vec3 offset_b; // t_ab - pos0
    std::vector<Vec3> curve;
    std::vector<Vec3> cap_verts; // N_caps + 1
    int n_caps = 0;
    double R_cap_outer = 0.118;
    double R_tube_nom = 0.10663;

    // 3D SDF grid (3.0 mm resolution)
    double h = 0.003;
    double inv_h = 1.0 / 0.003;
    Vec3 gmin = {-0.24, -0.29, -0.34};
    int nx = 0, ny = 0, nz = 0;
    std::vector<int16_t> sdf; // 0.1 mm units (1e-4 m)

    // Query surface points (strided / randomized)
    std::vector<Point3f> pts_q;
    int n_query_full = 0; // we keep ~24,000 points for full check, first 2,000 for coarse check

    // Canonical AABB of surface
    Vec3 surf_min = {-0.076, -0.128, -0.176};
    Vec3 surf_max = { 2.351,  1.580,  0.428};

    void init(const char* raw_path = "/app/raw_geom.bin", const char* cache_path = "/app/sdf_3mm.bin") {
        FILE* fp = std::fopen(raw_path, "rb");
        if (!fp) { std::perror("open raw_geom.bin"); std::exit(1); }
        double r_buf[9], t_buf[3], p_buf[3];
        if (std::fread(r_buf, sizeof(double), 9, fp) != 9) std::exit(1);
        if (std::fread(t_buf, sizeof(double), 3, fp) != 3) std::exit(1);
        if (std::fread(p_buf, sizeof(double), 3, fp) != 3) std::exit(1);
        for (int i = 0; i < 3; ++i)
            for (int j = 0; j < 3; ++j)
                R_ab.m[i][j] = r_buf[i * 3 + j];
        t_ab = {t_buf[0], t_buf[1], t_buf[2]};
        pos0 = {p_buf[0], p_buf[1], p_buf[2]};
        offset_b = t_ab - pos0;

        int32_t counts[4];
        if (std::fread(counts, sizeof(int32_t), 4, fp) != 4) std::exit(1);
        int n_curve = counts[0], n_cv = counts[1], n_surf = counts[2], n_pq = counts[3];

        curve.resize(n_curve);
        std::fread(curve.data(), sizeof(Vec3), n_curve, fp);
        cap_verts.resize(n_cv);
        std::fread(cap_verts.data(), sizeof(Vec3), n_cv, fp);
        n_caps = n_cv - 1;

        std::vector<Point3f> surf_3mm(n_surf);
        std::fread(surf_3mm.data(), sizeof(Point3f), n_surf, fp);

        std::vector<Point3f> all_pq(n_pq);
        std::fread(all_pq.data(), sizeof(Point3f), n_pq, fp);
        std::fclose(fp);

        // Keep up to 24,000 query points (since all_pq is randomly permuted, prefix is uniform + includes rims!)
        n_query_full = std::min(n_pq, 24000);
        pts_q.assign(all_pq.begin(), all_pq.begin() + n_query_full);

        // Compute exact R_cap_outer over surf_3mm
        double max_d2 = 0.0;
        #pragma omp parallel for reduction(max:max_d2)
        for (int i = 0; i < n_surf; ++i) {
            Vec3 p(surf_3mm[i].x, surf_3mm[i].y, surf_3mm[i].z);
            double bd2 = 1e18;
            for (int j = 0; j < n_caps; ++j) {
                Vec3 ab = cap_verts[j + 1] - cap_verts[j];
                double s = std::clamp((p - cap_verts[j]).dot(ab) / ab.norm2(), 0.0, 1.0);
                double d2 = (p - (cap_verts[j] + ab * s)).norm2();
                if (d2 < bd2) bd2 = d2;
            }
            if (bd2 > max_d2) max_d2 = bd2;
        }
        R_cap_outer = std::sqrt(max_d2) + 0.0015;

        Vec3 gmax = {2.52, 1.75, 0.59};
        nx = int(std::ceil((gmax.x - gmin.x) / h)) + 1;
        ny = int(std::ceil((gmax.y - gmin.y) / h)) + 1;
        nz = int(std::ceil((gmax.z - gmin.z) / h)) + 1;
        size_t total_vox = size_t(nx) * size_t(ny) * size_t(nz);
        sdf.resize(total_vox);

        FILE* cf = std::fopen(cache_path, "rb");
        if (cf) {
            size_t nr = std::fread(sdf.data(), sizeof(int16_t), total_vox, cf);
            std::fclose(cf);
            if (nr == total_vox) {
                return;
            }
        }

        auto t_start = std::chrono::steady_clock::now();
        // Compute outward normals for surf_3mm
        std::vector<Point3f> surf_norm(n_surf);
        #pragma omp parallel for
        for (int i = 0; i < n_surf; ++i) {
            Vec3 p(surf_3mm[i].x, surf_3mm[i].y, surf_3mm[i].z);
            if (p.x > 2.3465 && p.y > 0.75 && p.z < 0.08) {
                surf_norm[i] = {1.0f, 0.0f, 0.0f};
                continue;
            }
            if (p.y > 1.5755 && p.x > 0.80 && p.z > 0.18) {
                surf_norm[i] = {0.0f, 1.0f, 0.0f};
                continue;
            }
            double bd2 = 1e18;
            Vec3 bcp;
            for (size_t j = 0; j + 1 < curve.size(); ++j) {
                Vec3 ab = curve[j + 1] - curve[j];
                double s = std::clamp((p - curve[j]).dot(ab) / ab.norm2(), 0.0, 1.0);
                Vec3 cp = curve[j] + ab * s;
                double d2 = (p - cp).norm2();
                if (d2 < bd2) { bd2 = d2; bcp = cp; }
            }
            Vec3 n = (p - bcp).normalized();
            surf_norm[i] = {float(n.x), float(n.y), float(n.z)};
        }

        // Build uniform spatial grid (cell = 0.02m = 2cm) over surf_3mm for ultra-fast nearest surface query!
        const double cs = 0.02;
        const Vec3 bmin = {-0.30, -0.35, -0.40};
        const int bx = 145, by = 110, bz = 55;
        const int n_cells = bx * by * bz;
        std::vector<int> cell_head(n_cells + 1, 0);
        std::vector<int> pt_cell(n_surf);
        for (int i = 0; i < n_surf; ++i) {
            int cx = std::clamp(int((surf_3mm[i].x - bmin.x) / cs), 0, bx - 1);
            int cy = std::clamp(int((surf_3mm[i].y - bmin.y) / cs), 0, by - 1);
            int cz = std::clamp(int((surf_3mm[i].z - bmin.z) / cs), 0, bz - 1);
            int cid = (cx * by + cy) * bz + cz;
            pt_cell[i] = cid;
            cell_head[cid + 1]++;
        }
        for (int c = 0; c < n_cells; ++c) cell_head[c + 1] += cell_head[c];
        std::vector<int> cell_pts(n_surf);
        std::vector<int> cursor = cell_head;
        for (int i = 0; i < n_surf; ++i) {
            cell_pts[cursor[pt_cell[i]]++] = i;
        }

        // Compute 3D SDF across all Z/X slices in parallel!
        #pragma omp parallel for schedule(dynamic, 2)
        for (int ix = 0; ix < nx; ++ix) {
            double x = gmin.x + ix * h;
            for (int iy = 0; iy < ny; ++iy) {
                double y = gmin.y + iy * h;
                for (int iz = 0; iz < nz; ++iz) {
                    double z = gmin.z + iz * h;
                    Vec3 g(x, y, z);
                    // Coarse centerline distance
                    double cd2 = 1e18;
                    int best_seg = 0;
                    for (int j = 0; j < n_caps; ++j) {
                        Vec3 ab = cap_verts[j + 1] - cap_verts[j];
                        double s = std::clamp((g - cap_verts[j]).dot(ab) / ab.norm2(), 0.0, 1.0);
                        double d2 = (g - (cap_verts[j] + ab * s)).norm2();
                        if (d2 < cd2) { cd2 = d2; best_seg = j; }
                    }
                    double cd = std::sqrt(cd2);
                    double signed_d = cd - R_cap_outer;
                    if (cd < 0.165) {
                        // Exact search in 2cm spatial grid!
                        int gx0 = int((x - bmin.x) / cs);
                        int gy0 = int((y - bmin.y) / cs);
                        int gz0 = int((z - bmin.z) / cs);
                        // Search radius up to +-4 cells (8cm; if cd < 0.165, distance to surface is <= 0.075m!)
                        int rad = (cd > 0.045 && cd < 0.145) ? 3 : 5;
                        float best_sd2 = 1e18f;
                        int best_idx = -1;
                        for (int dx = -rad; dx <= rad; ++dx) {
                            int cx = gx0 + dx;
                            if (cx < 0 || cx >= bx) continue;
                            for (int dy = -rad; dy <= rad; ++dy) {
                                int cy = gy0 + dy;
                                if (cy < 0 || cy >= by) continue;
                                for (int dz = -rad; dz <= rad; ++dz) {
                                    int cz = gz0 + dz;
                                    if (cz < 0 || cz >= bz) continue;
                                    int cid = (cx * by + cy) * bz + cz;
                                    for (int p_it = cell_head[cid]; p_it < cell_head[cid + 1]; ++p_it) {
                                        int pid = cell_pts[p_it];
                                        float ex = float(x) - surf_3mm[pid].x;
                                        float ey = float(y) - surf_3mm[pid].y;
                                        float ez = float(z) - surf_3mm[pid].z;
                                        float sd2 = ex * ex + ey * ey + ez * ez;
                                        if (sd2 < best_sd2) {
                                            best_sd2 = sd2;
                                            best_idx = pid;
                                        }
                                    }
                                }
                            }
                        }
                        if (best_idx >= 0) {
                            double d_surf = std::sqrt(double(best_sd2));
                            // Inside/outside test:
                            bool outside = true;
                            if (best_seg <= 2 && x > 2.3498) {
                                outside = true;
                            } else if (best_seg >= n_caps - 3 && y > 1.5787) {
                                outside = true;
                            } else if (cd < 0.096) {
                                outside = false;
                            } else if (cd > 0.114) {
                                outside = true;
                            } else {
                                double dot = (x - surf_3mm[best_idx].x) * surf_norm[best_idx].x
                                           + (y - surf_3mm[best_idx].y) * surf_norm[best_idx].y
                                           + (z - surf_3mm[best_idx].z) * surf_norm[best_idx].z;
                                outside = (dot >= 0.0);
                            }
                            signed_d = outside ? d_surf : -d_surf;
                        }
                    }
                    int val = std::clamp(int(std::llround(signed_d * 10000.0)), -32000, 32000);
                    sdf[(size_t(ix) * ny + iy) * nz + iz] = int16_t(val);
                }
            }
        }
        auto t_end = std::chrono::steady_clock::now();
        double dt = std::chrono::duration<double>(t_end - t_start).count();
        std::printf("[AlphaModel] Built %dx%dx%d SDF in %.2f s (R_cap_outer=%.5f)\n",
                    nx, ny, nz, dt, R_cap_outer);

        FILE* out = std::fopen(cache_path, "wb");
        if (out) {
            std::fwrite(sdf.data(), sizeof(int16_t), total_vox, out);
            std::fclose(out);
        }
    }

    inline void pose_to_canonical(const Pose& pose, Mat3& R_can, Vec3& t_can) const {
        Mat3 R_q = Mat3::from_quat(pose.q);
        R_can = R_q * R_ab;
        t_can = R_q * offset_b + pose.p;
    }

    // Trilinear lookup in SDF_A (returns signed distance in metres; > 0.14m outside grid)
    inline double lookup_sdf(const Vec3& p) const {
        double gx = (p.x - gmin.x) * inv_h;
        double gy = (p.y - gmin.y) * inv_h;
        double gz = (p.z - gmin.z) * inv_h;
        if (gx < 0.0 || gy < 0.0 || gz < 0.0 || gx >= nx - 1 || gy >= ny - 1 || gz >= nz - 1) {
            // Distance to surf AABB [surf_min, surf_max]
            double dx = std::max({0.0, surf_min.x - p.x, p.x - surf_max.x});
            double dy = std::max({0.0, surf_min.y - p.y, p.y - surf_max.y});
            double dz = std::max({0.0, surf_min.z - p.z, p.z - surf_max.z});
            return std::sqrt(dx * dx + dy * dy + dz * dz);
        }
        int x0 = int(gx), y0 = int(gy), z0 = int(gz);
        double fx = gx - x0, fy = gy - y0, fz = gz - z0;
        size_t base = (size_t(x0) * ny + y0) * nz + z0;
        size_t sy = nz;
        size_t sx = size_t(ny) * nz;
        double c000 = sdf[base];
        double c100 = sdf[base + sx];
        double c010 = sdf[base + sy];
        double c110 = sdf[base + sx + sy];
        double c001 = sdf[base + 1];
        double c101 = sdf[base + sx + 1];
        double c011 = sdf[base + sy + 1];
        double c111 = sdf[base + sx + sy + 1];
        double c00 = c000 + fx * (c100 - c000);
        double c10 = c010 + fx * (c110 - c010);
        double c01 = c001 + fx * (c101 - c001);
        double c11 = c011 + fx * (c111 - c011);
        double c0 = c00 + fy * (c10 - c00);
        double c1 = c01 + fy * (c11 - c01);
        return (c0 + fz * (c1 - c0)) * 1e-4;
    }

    // Check workspace bounds on handle (= pose.p)
    inline bool in_workspace(const Pose& pose, double margin = 0.02) const {
        double lo = -0.8 + margin;
        double hi =  3.2 - margin;
        return pose.p.x >= lo && pose.p.x <= hi &&
               pose.p.y >= lo && pose.p.y <= hi &&
               pose.p.z >= lo && pose.p.z <= hi;
    }

    // Exact clearance with capsule broadphase + symmetric strided SDF narrowphase
    double exact_clearance(const Pose& pose, double early_exit_below = -1e9, double skip_sdf_above = 0.055) const {
        Mat3 R_can;
        Vec3 t_can;
        pose_to_canonical(pose, R_can, t_can);

        // Transform B's 49 capsule vertices and compute AABB of B
        Vec3 bv[64];
        Vec3 bmin(1e9, 1e9, 1e9), bmax(-1e9, -1e9, -1e9);
        for (int i = 0; i <= n_caps; ++i) {
            bv[i] = R_can * cap_verts[i] + t_can;
            bmin.x = std::min(bmin.x, bv[i].x); bmax.x = std::max(bmax.x, bv[i].x);
            bmin.y = std::min(bmin.y, bv[i].y); bmax.y = std::max(bmax.y, bv[i].y);
            bmin.z = std::min(bmin.z, bv[i].z); bmax.z = std::max(bmax.z, bv[i].z);
        }
        // Expand by R_cap_outer and check AABB separation vs A
        double r_exp = R_cap_outer;
        double ax_sep = std::max({0.0, (surf_min.x - bmax.x - r_exp), (bmin.x - r_exp - surf_max.x)});
        double ay_sep = std::max({0.0, (surf_min.y - bmax.y - r_exp), (bmin.y - r_exp - surf_max.y)});
        double az_sep = std::max({0.0, (surf_min.z - bmax.z - r_exp), (bmin.z - r_exp - surf_max.z)});
        double aabb_d = std::sqrt(ax_sep * ax_sep + ay_sep * ay_sep + az_sep * az_sep);
        if (aabb_d >= skip_sdf_above) return aabb_d;

        // 48x48 capsule centerline distance
        double min_seg_d2 = 1e18;
        double min_interior_d2 = 1e18;
        for (int i = 0; i < n_caps; ++i) {
            bool int_i = (i >= 2 && i <= n_caps - 3);
            for (int j = 0; j < n_caps; ++j) {
                // Quick midpoint filter
                Vec3 diff = cap_verts[i] - bv[j];
                if (diff.norm2() > min_seg_d2 + 0.08) continue;
                double d2 = seg_seg_dist2(cap_verts[i], cap_verts[i + 1], bv[j], bv[j + 1]);
                if (d2 < min_seg_d2) min_seg_d2 = d2;
                if (int_i && j >= 2 && j <= n_caps - 3 && d2 < min_interior_d2) min_interior_d2 = d2;
            }
        }
        double cap_lb = std::sqrt(min_seg_d2) - 2.0 * R_cap_outer;
        if (cap_lb >= skip_sdf_above) return cap_lb;
        // Deep interior penetration early exit (< 2 * 0.097m = 0.194m -> clearance <= -0.008m)
        if (min_interior_d2 < 0.192 * 0.192 && early_exit_below > -0.006) {
            return std::sqrt(min_interior_d2) - 2.0 * R_tube_nom;
        }

        Mat3 R_inv = R_can.T();
        Vec3 t_inv = R_inv * (t_can * -1.0);

        double min_d = 1e9;
        const int coarse_n = std::min(1500, n_query_full);
        // Pass 1: Coarse 1500 points (both B in SDF_A and A in SDF_B)
        for (int i = 0; i < coarse_n; ++i) {
            Vec3 p(pts_q[i].x, pts_q[i].y, pts_q[i].z);
            double db = lookup_sdf(R_can * p + t_can);
            if (db < min_d) {
                min_d = db;
                if (min_d < early_exit_below) return min_d;
            }
            double da = lookup_sdf(R_inv * p + t_inv);
            if (da < min_d) {
                min_d = da;
                if (min_d < early_exit_below) return min_d;
            }
        }
        // If even coarse points are all > 0.065m, surface can't be closer than ~0.045m
        if (min_d > skip_sdf_above + 0.025) return min_d - 0.01;

        // Pass 2: Remaining points up to n_query_full
        for (int i = coarse_n; i < n_query_full; ++i) {
            Vec3 p(pts_q[i].x, pts_q[i].y, pts_q[i].z);
            double db = lookup_sdf(R_can * p + t_can);
            if (db < min_d) {
                min_d = db;
                if (min_d < early_exit_below) return min_d;
            }
            double da = lookup_sdf(R_inv * p + t_inv);
            if (da < min_d) {
                min_d = da;
                if (min_d < early_exit_below) return min_d;
            }
        }
        return min_d;
    }

    // Fast analytical repulsive retraction using capsule pairs + SDF refinement
    bool retract_to_clearance(Pose& pose, double target_clr, int max_iters = 12) const {
        for (int it = 0; it < max_iters; ++it) {
            if (!in_workspace(pose, 0.03)) return false;
            double clr = exact_clearance(pose, -1e9, target_clr + 0.015);
            if (clr >= target_clr) return true;

            // Compute smooth repulsive wrench from all capsule pairs within 2*R_tube + 0.045m
            Mat3 R_can;
            Vec3 t_can;
            pose_to_canonical(pose, R_can, t_can);
            Vec3 bv[64];
            for (int i = 0; i <= n_caps; ++i) bv[i] = R_can * cap_verts[i] + t_can;

            Vec3 force(0, 0, 0), torque(0, 0, 0);
            const double thresh = 2.0 * R_tube_nom + 0.055;
            const double thresh2 = thresh * thresh;
            for (int i = 0; i < n_caps; ++i) {
                for (int j = 0; j < n_caps; ++j) {
                    Vec3 cpA, cpB;
                    double d2 = seg_seg_dist2(cap_verts[i], cap_verts[i + 1], bv[j], bv[j + 1], &cpA, &cpB);
                    if (d2 < thresh2 && d2 > 1e-10) {
                        double d = std::sqrt(d2);
                        double pen = thresh - d;
                        Vec3 n = (cpB - cpA) * (1.0 / d); // points into B
                        Vec3 f = n * (pen * pen);
                        force += f;
                        torque += (cpB - pose.p).cross(f);
                    }
                }
            }
            double fn = force.norm();
            double tn = torque.norm();
            if (fn < 1e-9 && tn < 1e-9) break;

            double deficit = std::clamp(target_clr - clr + 0.003, 0.003, 0.025);
            // Scale translation & rotation step proportionally
            double scale = deficit / std::max(fn, tn + 1e-12);
            Vec3 dp = force * scale;
            Vec3 dw = torque * scale;
            if (dp.norm() > 0.025) dp = dp.normalized() * 0.025;
            if (dw.norm() > 0.040) dw = dw.normalized() * 0.040;

            Pose cand;
            cand.p = pose.p + dp;
            cand.q = Quat::from_rotvec(dw) * pose.q;
            cand.q.normalize();
            pose = cand;
        }
        return in_workspace(pose, 0.03) && exact_clearance(pose, target_clr, target_clr + 0.01) >= target_clr;
    }

    // Check continuous motion along edge [a, b] under BOTH uniform slerp/lerp AND independent speed limits!
    bool edge_valid(const Pose& a, const Pose& b, double min_clr, double* out_min_clr = nullptr) const {
        if (!in_workspace(a, 0.02) || !in_workspace(b, 0.02)) return false;
        double dp = (b.p - a.p).norm();
        double dq = a.q.angle_to(b.q);
        int n_steps = std::max({2, int(std::ceil(dp / 0.012)), int(std::ceil(dq / 0.020))});
        double worst = 1e9;

        // 1) Uniform interpolation
        for (int k = 1; k <= n_steps; ++k) {
            double s = double(k) / n_steps;
            Pose cur;
            cur.p = a.p + (b.p - a.p) * s;
            cur.q = Quat::slerp(a.q, b.q, s);
            double c = exact_clearance(cur, min_clr, min_clr + 0.02);
            if (c < worst) worst = c;
            if (c < min_clr) {
                if (out_min_clr) *out_min_clr = worst;
                return false;
            }
        }

        // 2) Independent velocity-limited interpolation (0.1 m/s linear, 0.1 rad/s angular)
        double tp = dp / 0.1;
        double tq = dq / 0.1;
        double T = std::max(tp, tq);
        if (T > 1e-6 && std::abs(tp - tq) > 0.03) {
            for (int k = 1; k < n_steps; ++k) {
                double t = (double(k) / n_steps) * T;
                double sp = (tp > 1e-8) ? std::min(1.0, t / tp) : 1.0;
                double sq = (tq > 1e-8) ? std::min(1.0, t / tq) : 1.0;
                Pose cur;
                cur.p = a.p + (b.p - a.p) * sp;
                cur.q = Quat::slerp(a.q, b.q, sq);
                double c = exact_clearance(cur, min_clr, min_clr + 0.02);
                if (c < worst) worst = c;
                if (c < min_clr) {
                    if (out_min_clr) *out_min_clr = worst;
                    return false;
                }
            }
        }
        if (out_min_clr) *out_min_clr = worst;
        return true;
    }

    // Check if from `pose`, tube_b can translate along some straight ray u in S^2 to infinity with clearance >= req_clr
    bool can_slide_to_infinity(const Pose& pose, double req_clr, Vec3* best_u = nullptr, double* best_ray_clr = nullptr) const {
        if (!in_workspace(pose, 0.02)) return false;
        double c0 = exact_clearance(pose, req_clr, 0.08);
        if (c0 < req_clr) return false;

        // Generate 180 Fibonacci directions on S^2
        static std::vector<Vec3> dirs;
        if (dirs.empty()) {
            const int N = 180;
            const double phi = M_PI * (3.0 - std::sqrt(5.0));
            for (int i = 0; i < N; ++i) {
                double y = 1.0 - (i / double(N - 1)) * 2.0;
                double r = std::sqrt(std::max(0.0, 1.0 - y * y));
                double th = phi * i;
                dirs.emplace_back(std::cos(th) * r, y, std::sin(th) * r);
            }
        }

        // Precompute B's 49 capsule vertices at `pose` for fast ray rejection
        Mat3 R_can;
        Vec3 t_can;
        pose_to_canonical(pose, R_can, t_can);
        Vec3 bv0[64];
        for (int i = 0; i <= n_caps; ++i) bv0[i] = R_can * cap_verts[i] + t_can;

        double max_found = -1e9;
        Vec3 best_dir(0, 0, 1);

        for (const Vec3& u : dirs) {
            // Quick coarse check along s = 0.08, 0.18, 0.30, ..., 2.80 using interior capsule lower bound
            bool blocked_caps = false;
            for (double s = 0.06; s <= 3.0; s += 0.08) {
                Vec3 shift = u * s;
                // Check interior segments (radius >= 0.098)
                for (int i = 2; i <= n_caps - 3 && !blocked_caps; i += 2) {
                    for (int j = 2; j <= n_caps - 3; j += 2) {
                        double d2 = seg_seg_dist2(cap_verts[i], cap_verts[i + 1], bv0[j] + shift, bv0[j + 1] + shift);
                        if (d2 < 0.194 * 0.194) { blocked_caps = true; break; }
                    }
                }
                if (blocked_caps) break;
            }
            if (blocked_caps) continue;

            // Exact SDF verification along ray s = 0.02, 0.04, ..., 3.20
            double ray_min = c0;
            bool ok = true;
            for (double s = 0.025; s <= 3.2; s += 0.025) {
                Pose shifted = {pose.p + u * s, pose.q};
                double c = exact_clearance(shifted, req_clr, req_clr + 0.03);
                if (c < ray_min) ray_min = c;
                if (c < req_clr) { ok = false; break; }
                // Once shifted past 2.8m and clearance > 0.3m, moving further only increases distance
                if (s > 1.2 && c > 0.35) s += 0.075;
            }
            if (ok && ray_min > max_found) {
                max_found = ray_min;
                best_dir = u;
                if (!best_ray_clr && max_found >= req_clr + 0.01) {
                    if (best_u) *best_u = best_dir;
                    return true;
                }
            }
        }
        if (max_found >= req_clr) {
            if (best_u) *best_u = best_dir;
            if (best_ray_clr) *best_ray_clr = max_found;
            return true;
        }
        return false;
    }
};

#include "alpha_sim.hpp"
#include <random>
#include <unordered_map>
#include <atomic>
#include <mutex>

struct Node {
    Pose pose;
    int parent;
};

struct RNG {
    std::mt19937_64 gen;
    RNG(uint64_t seed) : gen(seed) {}
    double uniform(double a = 0.0, double b = 1.0) {
        std::uniform_real_distribution<double> d(a, b);
        return d(gen);
    }
    double normal(double mu = 0.0, double sd = 1.0) {
        std::normal_distribution<double> d(mu, sd);
        return d(gen);
    }
    int randint(int lo, int hi) {
        std::uniform_int_distribution<int> d(lo, hi);
        return d(gen);
    }
    Quat rand_quat() {
        double u1 = uniform(), u2 = uniform(0, 2 * M_PI), u3 = uniform(0, 2 * M_PI);
        double s1 = std::sqrt(1.0 - u1), s2 = std::sqrt(u1);
        Quat q(s2 * std::cos(u3), s1 * std::sin(u2), s1 * std::cos(u2), s2 * std::sin(u3));
        q.normalize();
        return q;
    }
};

static inline double pose_dist(const Pose& a, const Pose& b) {
    return (a.p - b.p).norm() + 0.65 * a.q.angle_to(b.q);
}

static inline Pose interpolate_pose(const Pose& a, const Pose& b, double t) {
    return {a.p + (b.p - a.p) * t, Quat::slerp(a.q, b.q, t)};
}

struct CellKey {
    int64_t key;
    static int64_t compute(const Pose& p) {
        int ix = int(std::floor((p.p.x + 1.0) / 0.14));
        int iy = int(std::floor((p.p.y + 1.0) / 0.14));
        int iz = int(std::floor((p.p.z + 1.0) / 0.14));
        Vec3 rv = p.q.to_rotvec();
        int irx = int(std::floor((rv.x + 3.2) / 0.45));
        int iry = int(std::floor((rv.y + 3.2) / 0.45));
        int irz = int(std::floor((rv.z + 3.2) / 0.45));
        uint64_t h = uint64_t(ix & 0x3FF)
                   | (uint64_t(iy & 0x3FF) << 10)
                   | (uint64_t(iz & 0x3FF) << 20)
                   | (uint64_t(irx & 0xFF) << 30)
                   | (uint64_t(iry & 0xFF) << 38)
                   | (uint64_t(irz & 0xFF) << 46);
        return int64_t(h);
    }
};

struct Tree {
    std::vector<Node> nodes;
    std::unordered_map<int64_t, std::vector<int>> cells;
    std::vector<int64_t> cell_keys;

    int add_node(const Pose& p, int parent) {
        int id = int(nodes.size());
        nodes.push_back({p, parent});
        int64_t k = CellKey::compute(p);
        auto it = cells.find(k);
        if (it == cells.end()) {
            cell_keys.push_back(k);
            cells[k] = {id};
        } else {
            it->second.push_back(id);
        }
        return id;
    }

    int nearest(const Pose& target) const {
        int best = 0;
        double best_d = 1e18;
        int n = int(nodes.size());
        for (int i = 0; i < n; ++i) {
            // Fast lower bound using translation first
            double dp = (nodes[i].pose.p - target.p).norm();
            if (dp >= best_d) continue;
            double d = dp + 0.65 * nodes[i].pose.q.angle_to(target.q);
            if (d < best_d) { best_d = d; best = i; }
        }
        return best;
    }

    int pick_sparse_node(RNG& rng) const {
        // Sample 5 random cells and pick the one with fewest nodes!
        int best_c = rng.randint(0, int(cell_keys.size()) - 1);
        size_t best_sz = cells.at(cell_keys[best_c]).size();
        for (int t = 0; t < 4; ++t) {
            int c = rng.randint(0, int(cell_keys.size()) - 1);
            size_t sz = cells.at(cell_keys[c]).size();
            if (sz < best_sz) { best_sz = sz; best_c = c; }
        }
        const auto& vec = cells.at(cell_keys[best_c]);
        return vec[rng.randint(0, int(vec.size()) - 1)];
    }
};

enum ExtendStatus { TRAPPED, ADVANCED, REACHED };

// Extend tree toward target with medial-axis retraction when hitting narrow passage walls!
ExtendStatus extend_retracted(const AlphaModel& model, Tree& tree, int near_id, const Pose& target,
                              double plan_clr, double max_step, int& out_new_id, bool allow_retract = true) {
    const Pose& q_near = tree.nodes[near_id].pose;
    double d = pose_dist(q_near, target);
    bool reaching = (d <= max_step);
    Pose q_new = reaching ? target : interpolate_pose(q_near, target, max_step / d);

    if (model.edge_valid(q_near, q_new, plan_clr)) {
        out_new_id = tree.add_node(q_new, near_id);
        return reaching ? REACHED : ADVANCED;
    }

    if (!allow_retract) return TRAPPED;

    // Try retracting q_new onto medial axis / clearance >= plan_clr + 0.002!
    Pose q_ret = q_new;
    if (model.retract_to_clearance(q_ret, plan_clr + 0.002, 10)) {
        // Ensure retracted node actually made progress and isn't right on top of q_near
        double d_move = pose_dist(q_near, q_ret);
        if (d_move > 0.020 && d_move < max_step * 1.8 && model.edge_valid(q_near, q_ret, plan_clr)) {
            out_new_id = tree.add_node(q_ret, near_id);
            return ADVANCED;
        }
    }
    return TRAPPED;
}

ExtendStatus connect_retracted(const AlphaModel& model, Tree& tree, const Pose& target,
                               double plan_clr, double max_step, int& last_id) {
    int cur = tree.nearest(target);
    last_id = cur;
    for (int steps = 0; steps < 80; ++steps) {
        int next_id = -1;
        ExtendStatus st = extend_retracted(model, tree, cur, target, plan_clr, max_step, next_id, steps < 12);
        if (st == TRAPPED) return (steps > 0) ? ADVANCED : TRAPPED;
        cur = next_id;
        last_id = cur;
        if (st == REACHED) return REACHED;
    }
    return ADVANCED;
}

// Fine 6D clearance maximization along dense path using exact_clearance finite differences!
void maximize_path_clearance(const AlphaModel& model, std::vector<Pose>& path, int iters = 25) {
    int n = int(path.size());
    for (int it = 0; it < iters; ++it) {
        std::vector<Pose> next_path = path;
        #pragma omp parallel for schedule(dynamic, 4)
        for (int i = 1; i < n - 1; ++i) {
            Pose cur = path[i];
            double c0 = model.exact_clearance(cur, -1e9, 0.07);
            if (c0 > 0.042) {
                // Plenty of clearance; just lightly smooth toward neighbors
                Pose mid = interpolate_pose(path[i - 1], path[i + 1], 0.5);
                Pose cand = interpolate_pose(cur, mid, 0.25);
                if (model.exact_clearance(cand, 0.035, 0.06) >= 0.035) next_path[i] = cand;
                continue;
            }
            // Compute 6D numerical gradient of exact_clearance!
            const double eps_p = 0.0025;
            const double eps_q = 0.0050;
            Vec3 gp;
            gp.x = (model.exact_clearance({cur.p + Vec3(eps_p, 0, 0), cur.q}, -1e9, 0.08) -
                    model.exact_clearance({cur.p - Vec3(eps_p, 0, 0), cur.q}, -1e9, 0.08)) / (2 * eps_p);
            gp.y = (model.exact_clearance({cur.p + Vec3(0, eps_p, 0), cur.q}, -1e9, 0.08) -
                    model.exact_clearance({cur.p - Vec3(0, eps_p, 0), cur.q}, -1e9, 0.08)) / (2 * eps_p);
            gp.z = (model.exact_clearance({cur.p + Vec3(0, 0, eps_p), cur.q}, -1e9, 0.08) -
                    model.exact_clearance({cur.p - Vec3(0, 0, eps_p), cur.q}, -1e9, 0.08)) / (2 * eps_p);

            Vec3 gq;
            gq.x = (model.exact_clearance({cur.p, Quat::from_rotvec({eps_q, 0, 0}) * cur.q}, -1e9, 0.08) -
                    model.exact_clearance({cur.p, Quat::from_rotvec({-eps_q, 0, 0}) * cur.q}, -1e9, 0.08)) / (2 * eps_q);
            gq.y = (model.exact_clearance({cur.p, Quat::from_rotvec({0, eps_q, 0}) * cur.q}, -1e9, 0.08) -
                    model.exact_clearance({cur.p, Quat::from_rotvec({0, -eps_q, 0}) * cur.q}, -1e9, 0.08)) / (2 * eps_q);
            gq.z = (model.exact_clearance({cur.p, Quat::from_rotvec({0, 0, eps_q}) * cur.q}, -1e9, 0.08) -
                    model.exact_clearance({cur.p, Quat::from_rotvec({0, 0, -eps_q}) * cur.q}, -1e9, 0.08)) / (2 * eps_q);

            double gn = std::sqrt(gp.norm2() + gq.norm2());
            if (gn < 1e-6) continue;

            Pose mid = interpolate_pose(path[i - 1], path[i + 1], 0.5);
            for (double step : {0.006, 0.003, 0.0015}) {
                Pose cand;
                cand.p = cur.p + gp * (step / gn);
                cand.q = Quat::from_rotvec(gq * (step * 1.5 / gn)) * cur.q;
                cand.q.normalize();
                // Blend 15% spring smoothing toward midpoint so waypoints stay evenly spaced
                cand = interpolate_pose(cand, mid, 0.15);
                if (!model.in_workspace(cand, 0.03)) continue;
                double c_new = model.exact_clearance(cand, c0, 0.08);
                if (c_new > c0 && pose_dist(path[i - 1], cand) < 0.09 && pose_dist(cand, path[i + 1]) < 0.09) {
                    next_path[i] = cand;
                    break;
                }
            }
        }
        path = std::move(next_path);
    }
}

std::vector<Pose> densify_path(const std::vector<Pose>& path, double max_dp = 0.022, double max_dq = 0.040) {
    std::vector<Pose> out;
    if (path.empty()) return out;
    out.push_back(path[0]);
    for (size_t i = 0; i + 1 < path.size(); ++i) {
        double dp = (path[i + 1].p - path[i].p).norm();
        double dq = path[i].q.angle_to(path[i + 1].q);
        int k = std::max({1, int(std::ceil(dp / max_dp)), int(std::ceil(dq / max_dq))});
        for (int s = 1; s <= k; ++s) {
            out.push_back(interpolate_pose(path[i], path[i + 1], double(s) / k));
        }
    }
    return out;
}

int main() {
    auto t0 = std::chrono::steady_clock::now();
    AlphaModel model;
    model.init();

    Pose start_pose = {{1.2, 0.36, 0.28}, {1.0, 0.0, 0.0, 0.0}};
    double start_clr = model.exact_clearance(start_pose, -1e9, 0.10);
    bool start_free = model.can_slide_to_infinity(start_pose, 0.001);
    std::printf("Start pose clearance = %.5f m, can_slide_to_infinity = %d\n", start_clr, int(start_free));

    // Build shared Goal seed poses (clearly disentangled poses around tube_a inside workspace)
    Pose root_goal = {{1.2, 2.35, 1.45}, {1.0, 0.0, 0.0, 0.0}};
    std::printf("Root goal clearance = %.5f m, free = %d\n",
                model.exact_clearance(root_goal, -1e9, 0.5),
                int(model.can_slide_to_infinity(root_goal, 0.05)));

    std::atomic<bool> solved{false};
    std::vector<Pose> best_raw_path;
    std::mutex sol_mtx;

    // Launch 10 parallel BiRRT-Connect workers with medial-axis retraction!
    const double margins[10] = {0.008, 0.007, 0.007, 0.006, 0.006, 0.0055, 0.005, 0.005, 0.0045, 0.004};

    #pragma omp parallel num_threads(10)
    {
        int tid = omp_get_thread_num();
        double plan_clr = margins[tid];
        RNG rng(10007ULL * (tid + 1) + 42ULL);

        Tree t_start, t_goal;
        t_start.add_node(start_pose, -1);
        t_goal.add_node(root_goal, -1);

        // Add 25 diverse disentangled goal poses connected directly to root_goal
        for (int g = 0; g < 60 && t_goal.nodes.size() < 26; ++g) {
            Pose gp;
            gp.p = {rng.uniform(-0.3, 2.6), rng.uniform(-0.4, 2.7), rng.uniform(0.7, 2.4)};
            gp.q = rng.rand_quat();
            if (model.exact_clearance(gp, 0.15, 0.20) >= 0.15 &&
                model.edge_valid(root_goal, gp, 0.05) &&
                model.can_slide_to_infinity(gp, 0.05)) {
                t_goal.add_node(gp, 0);
            }
        }

        const double max_step = 0.13;
        bool swap_trees = false;

        for (int iter = 0; iter < 150000 && !solved.load(std::memory_order_relaxed); ++iter) {
            Tree& ta = swap_trees ? t_goal : t_start;
            Tree& tb = swap_trees ? t_start : t_goal;
            swap_trees = !swap_trees;

            Pose q_rand;
            double mode = rng.uniform();
            int near_a = -1;

            if (mode < 0.35) {
                // Sparse frontier cell expansion! Pick sparse cell node and perturb locally
                near_a = ta.pick_sparse_node(rng);
                const Pose& base = ta.nodes[near_a].pose;
                double r_p = rng.uniform(0.08, 0.32);
                double r_q = rng.uniform(0.12, 0.55);
                Vec3 dp(rng.normal(), rng.normal(), rng.normal());
                Vec3 dw(rng.normal(), rng.normal(), rng.normal());
                q_rand.p = base.p + dp.normalized() * r_p;
                q_rand.q = Quat::from_rotvec(dw.normalized() * r_q) * base.q;
                q_rand.q.normalize();
            } else if (mode < 0.80) {
                // Tight interaction box around tube_a loop & legs!
                q_rand.p = {rng.uniform(-0.45, 2.55), rng.uniform(-0.55, 2.15), rng.uniform(-0.55, 1.45)};
                q_rand.q = rng.rand_quat();
            } else {
                // Wider workspace box
                q_rand.p = {rng.uniform(-0.65, 2.95), rng.uniform(-0.65, 2.95), rng.uniform(-0.65, 2.65)};
                q_rand.q = rng.rand_quat();
            }

            if (!model.in_workspace(q_rand, 0.04)) continue;
            if (near_a < 0) near_a = ta.nearest(q_rand);

            int new_a = -1;
            ExtendStatus st_a = extend_retracted(model, ta, near_a, q_rand, plan_clr, max_step, new_a, true);
            if (st_a == TRAPPED) continue;

            // Check if if ta IS t_start and the newly added node CAN ALREADY SLIDE TO INFINITY!
            bool ta_is_start = (&ta == &t_start);
            if (ta_is_start && (ta.nodes.size() % 4 == 0)) {
                const Pose& qn = ta.nodes[new_a].pose;
                if (model.exact_clearance(qn, 0.03, 0.05) >= 0.03 && model.can_slide_to_infinity(qn, 0.025)) {
                    std::lock_guard<std::mutex> lk(sol_mtx);
                    if (!solved.load()) {
                        solved.store(true);
                        std::vector<Pose> p;
                        for (int cur = new_a; cur != -1; cur = ta.nodes[cur].parent) p.push_back(ta.nodes[cur].pose);
                        std::reverse(p.begin(), p.end());
                        best_raw_path = std::move(p);
                        std::printf("[Thread %d, margin=%.4f] Direct escape found at iter %d (|T_s|=%zu)!\n",
                                    tid, plan_clr, iter, t_start.nodes.size());
                    }
                    break;
                }
            }

            // Try RRT-Connect from tb toward ta.nodes[new_a].pose!
            int last_b = -1;
            ExtendStatus st_b = connect_retracted(model, tb, ta.nodes[new_a].pose, plan_clr, max_step, last_b);
            if (st_b == REACHED) {
                std::lock_guard<std::mutex> lk(sol_mtx);
                if (!solved.load()) {
                    solved.store(true);
                    int id_s = ta_is_start ? new_a : last_b;
                    int id_g = ta_is_start ? last_b : new_a;
                    std::vector<Pose> ps, pg;
                    for (int cur = id_s; cur != -1; cur = t_start.nodes[cur].parent) ps.push_back(t_start.nodes[cur].pose);
                    std::reverse(ps.begin(), ps.end());
                    for (int cur = t_goal.nodes[id_g].parent; cur != -1; cur = t_goal.nodes[cur].parent) pg.push_back(t_goal.nodes[cur].pose);
                    ps.insert(ps.end(), pg.begin(), pg.end());
                    best_raw_path = std::move(ps);
                    std::printf("[Thread %d, margin=%.4f] Trees connected at iter %d (|T_s|=%zu, |T_g|=%zu, raw len=%zu)!\n",
                                tid, plan_clr, iter, t_start.nodes.size(), t_goal.nodes.size(), best_raw_path.size());
                }
                break;
            }

            if (tid == 0 && iter % 5000 == 0 && iter > 0) {
                std::printf("  [iter %d] |T_start|=%zu (%zu cells), |T_goal|=%zu (%zu cells)\n",
                            iter, t_start.nodes.size(), t_start.cell_keys.size(),
                            t_goal.nodes.size(), t_goal.cell_keys.size());
                std::fflush(stdout);
            }
        }
    }

    if (!solved.load()) {
        std::printf("FAILED to find path within iteration limit!\n");
        return 1;
    }

    auto t_found = std::chrono::steady_clock::now();
    std::printf("Path found in %.2f s! Optimizing clearance & action count...\n",
                std::chrono::duration<double>(t_found - t0).count());

    // 1. Truncate raw path at earliest pose with can_slide_to_infinity >= 0.025m!
    std::vector<Pose> dense = densify_path(best_raw_path, 0.020, 0.035);
    size_t cut_idx = dense.size() - 1;
    for (size_t i = 1; i < dense.size(); ++i) {
        if (model.can_slide_to_infinity(dense[i], 0.025)) {
            cut_idx = i;
            break;
        }
    }
    dense.resize(cut_idx + 1);
    std::printf("Truncated dense path to %zu states (first state with >=25mm ray escape).\n", dense.size());

    // 2. Maximize clearance along the dense path!
    maximize_path_clearance(model, dense, 35);
    dense = densify_path(dense, 0.018, 0.032);
    maximize_path_clearance(model, dense, 25);

    double min_dense_clr = 1e9;
    for (const auto& p : dense) {
        min_dense_clr = std::min(min_dense_clr, model.exact_clearance(p, -1e9, 0.10));
    }
    std::printf("After medial-axis clearance maximization: bottleneck clearance = %.5f m (%.2f mm)!\n",
                min_dense_clr, min_dense_clr * 1000.0);

    // 3. Randomized shortcutting preserving clearance >= safe_floor!
    double safe_floor = std::min(0.020, min_dense_clr - 0.0012);
    if (safe_floor < 0.005) safe_floor = std::max(0.004, min_dense_clr - 0.0005);
    std::printf("Running clearance-preserving shortcutting with floor = %.5f m...\n", safe_floor);

    RNG sc_rng(99999);
    for (int sc = 0; sc < 1500 && dense.size() > 4; ++sc) {
        int i = sc_rng.randint(0, int(dense.size()) - 3);
        int j = sc_rng.randint(i + 2, std::min(int(dense.size()) - 1, i + 45));
        if (model.edge_valid(dense[i], dense[j], safe_floor)) {
            // Replace [i..j] with densified straight segment
            std::vector<Pose> seg = densify_path({dense[i], dense[j]}, 0.018, 0.032);
            std::vector<Pose> next_d;
            next_d.insert(next_d.end(), dense.begin(), dense.begin() + i);
            next_d.insert(next_d.end(), seg.begin(), seg.end());
            next_d.insert(next_d.end(), dense.begin() + j + 1, dense.end());
            dense = std::move(next_d);
        }
    }
    // Re-push clearance gently after shortcutting!
    maximize_path_clearance(model, dense, 15);
    dense = densify_path(dense, 0.014, 0.025);

    // Re-check earliest escape state on optimized curve (with >= 22mm ray escape clearance)!
    size_t final_cut = dense.size() - 1;
    Vec3 escape_dir(0, 0, 1);
    double escape_ray_clr = 0.0;
    for (size_t i = 1; i < dense.size(); ++i) {
        Vec3 u;
        double r_clr = 0.0;
        if (model.can_slide_to_infinity(dense[i], 0.022, &u, &r_clr)) {
            final_cut = i;
            escape_dir = u;
            escape_ray_clr = r_clr;
            break;
        }
    }
    dense.resize(final_cut + 1);
    std::printf("Post-shortcut earliest escape at dense[%zu], escape_ray_clr=%.4f m, dir=(%.3f, %.3f, %.3f)\n",
                final_cut, escape_ray_clr, escape_dir.x, escape_dir.y, escape_dir.z);

    // 4. Globally Optimal Action-Step Discretization via DAG Shortest Path!
    // Limits per move: max_linear_step_m = 0.10, max_angular_step_rad = 0.20.
    // Use 0.095 m and 0.190 rad so closed-loop execution has comfortable margin without clamping!
    const double step_lin_lim = 0.095;
    const double step_ang_lim = 0.190;
    int M = int(dense.size());
    std::vector<int> dp_steps(M, 1e9);
    std::vector<double> dp_bottleneck(M, -1e9);
    std::vector<int> dp_prev(M, -1);
    dp_steps[0] = 0;
    dp_bottleneck[0] = start_clr;

    for (int i = 0; i < M; ++i) {
        if (dp_steps[i] >= 1e8) continue;
        for (int j = i + 1; j < M; ++j) {
            double dlin = (dense[j].p - dense[i].p).norm();
            double dang = dense[i].q.angle_to(dense[j].q);
            if (dlin > step_lin_lim || dang > step_ang_lim) {
                // Note: curve might bend slightly, so only break if well beyond limit
                if (dlin > step_lin_lim * 1.35 || dang > step_ang_lim * 1.35) break;
                continue;
            }
            double edge_clr = 0.0;
            if (!model.edge_valid(dense[i], dense[j], safe_floor, &edge_clr)) continue;
            int cand_steps = dp_steps[i] + 1;
            double cand_bn = std::min(dp_bottleneck[i], edge_clr);
            if (cand_steps < dp_steps[j] || (cand_steps == dp_steps[j] && cand_bn > dp_bottleneck[j])) {
                dp_steps[j] = cand_steps;
                dp_bottleneck[j] = cand_bn;
                dp_prev[j] = i;
            }
        }
    }

    if (dp_steps[M - 1] >= 1e8) {
        std::printf("DP failed at safe_floor=%.5f, relaxing floor slightly...\n", safe_floor);
        return 1;
    }

    std::vector<Pose> waypoints;
    for (int cur = M - 1; cur != -1; cur = dp_prev[cur]) waypoints.push_back(dense[cur]);
    std::reverse(waypoints.begin(), waypoints.end());

    // Append 5 backup steps sliding straight out along escape_dir (0.092m each)!
    // Remember: simulator ends IMMEDIATELY when success: true, so backup steps cost 0 if already solved!
    Pose tail = waypoints.back();
    for (int b = 1; b <= 5; ++b) {
        Pose next_tail = {tail.p + escape_dir * (0.092 * b), tail.q};
        if (model.in_workspace(next_tail, 0.03) && model.edge_valid(waypoints.back(), next_tail, 0.020)) {
            waypoints.push_back(next_tail);
        } else {
            break;
        }
    }

    std::printf("\n=== PLANNED TRAJECTORY SUMMARY ===\n");
    std::printf("Waypoints to escape pose: %d moves (+1 grab = %d actions! Expected score ~ %.4f)\n",
                dp_steps[M - 1], dp_steps[M - 1] + 1, 1.0 - 0.5 * ((dp_steps[M - 1] + 1) / 198.0));
    std::printf("Total waypoints (including backup escape slide): %zu\n", waypoints.size() - 1);
    std::printf("Guaranteed minimum continuous surface clearance: %.4f m (%.2f mm)\n",
                dp_bottleneck[M - 1], dp_bottleneck[M - 1] * 1000.0);

    FILE* out = std::fopen("/app/plan.txt", "w");
    for (size_t i = 0; i < waypoints.size(); ++i) {
        const Pose& w = waypoints[i];
        double clr = model.exact_clearance(w, -1e9, 0.20);
        double dlin = (i > 0) ? (w.p - waypoints[i - 1].p).norm() : 0.0;
        double dang = (i > 0) ? waypoints[i - 1].q.angle_to(w.q) : 0.0;
        std::fprintf(out, "%.8f %.8f %.8f %.8f %.8f %.8f %.8f\n",
                     w.p.x, w.p.y, w.p.z, w.q.w, w.q.x, w.q.y, w.q.z);
        std::printf("  [%2zu] pos=(%7.4f, %7.4f, %7.4f) quat=(%7.4f, %7.4f, %7.4f, %7.4f) | dp=%.4f dq=%.4f clr=%.4fm\n",
                    i, w.p.x, w.p.y, w.p.z, w.q.w, w.q.x, w.q.y, w.q.z, dlin, dang, clr);
    }
    std::fclose(out);
    return 0;
}

