// Exact clearance with 8-group capsule BVH + per-segment bucketed SDF narrowphase (~3 us!)
double exact_clearance(const Pose& pose, double early_exit_below = -1e9, double skip_sdf_above = 0.055) const {
    Mat3 R_can;
    Vec3 t_can;
    pose_to_canonical(pose, R_can, t_can);

    // Transform B's 49 capsule vertices and compute 8 group AABBs + overall AABB of B
    Vec3 bv[64];
    Vec3 bmin(1e9, 1e9, 1e9), bmax(-1e9, -1e9, -1e9);
    for (int i = 0; i <= n_caps; ++i) {
        bv[i] = R_can * cap_verts[i] + t_can;
        bmin.x = std::min(bmin.x, bv[i].x); bmax.x = std::max(bmax.x, bv[i].x);
        bmin.y = std::min(bmin.y, bv[i].y); bmax.y = std::max(bmax.y, bv[i].y);
        bmin.z = std::min(bmin.z, bv[i].z); bmax.z = std::max(bmax.z, bv[i].z);
    }
    double r_exp = R_cap_outer;
    double ax_sep = std::max({0.0, (surf_min.x - bmax.x - r_exp), (bmin.x - r_exp - surf_max.x)});
    double ay_sep = std::max({0.0, (surf_min.y - bmax.y - r_exp), (bmin.y - r_exp - surf_max.y)});
    double az_sep = std::max({0.0, (surf_min.z - bmax.z - r_exp), (bmin.z - r_exp - surf_max.z)});
    double aabb_d = std::sqrt(ax_sep * ax_sep + ay_sep * ay_sep + az_sep * az_sep);
    if (aabb_d >= skip_sdf_above) return aabb_d;

    Vec3 grp_b_min[8], grp_b_max[8];
    for (int g = 0; g < 8; ++g) {
        Vec3 mn(1e9, 1e9, 1e9), mx(-1e9, -1e9, -1e9);
        int s0 = g * 6, s1 = std::min(n_caps, (g + 1) * 6);
        for (int v = s0; v <= s1; ++v) {
            mn.x = std::min(mn.x, bv[v].x); mx.x = std::max(mx.x, bv[v].x);
            mn.y = std::min(mn.y, bv[v].y); mx.y = std::max(mx.y, bv[v].y);
            mn.z = std::min(mn.z, bv[v].z); mx.z = std::max(mx.z, bv[v].z);
        }
        grp_b_min[g] = mn;
        grp_b_max[g] = mx;
    }

    double min_d2_A[64], min_d2_B[64];
    for (int i = 0; i < n_caps; ++i) { min_d2_A[i] = 1e18; min_d2_B[i] = 1e18; }
    double min_seg_d2 = 1e18;
    double min_interior_d2 = 1e18;
    const double grp_cutoff = 2.0 * R_cap_outer + skip_sdf_above + 0.01;
    const double grp_cutoff2 = grp_cutoff * grp_cutoff;

    for (int ga = 0; ga < 8; ++ga) {
        for (int gb = 0; gb < 8; ++gb) {
            double dx = std::max({0.0, grp_a_min[ga].x - grp_b_max[gb].x, grp_b_min[gb].x - grp_a_max[ga].x});
            double dy = std::max({0.0, grp_a_min[ga].y - grp_b_max[gb].y, grp_b_min[gb].y - grp_a_max[ga].y});
            double dz = std::max({0.0, grp_a_min[ga].z - grp_b_max[gb].z, grp_b_min[gb].z - grp_a_max[ga].z});
            if (dx * dx + dy * dy + dz * dz > grp_cutoff2) continue;

            int ia0 = ga * 6, ia1 = std::min(n_caps, (ga + 1) * 6);
            int jb0 = gb * 6, jb1 = std::min(n_caps, (gb + 1) * 6);
            for (int i = ia0; i < ia1; ++i) {
                bool int_i = (i >= 2 && i <= n_caps - 3);
                for (int j = jb0; j < jb1; ++j) {
                    double d2 = seg_seg_dist2(cap_verts[i], cap_verts[i + 1], bv[j], bv[j + 1]);
                    if (d2 < min_d2_A[i]) min_d2_A[i] = d2;
                    if (d2 < min_d2_B[j]) min_d2_B[j] = d2;
                    if (d2 < min_seg_d2) min_seg_d2 = d2;
                    if (int_i && j >= 2 && j <= n_caps - 3 && d2 < min_interior_d2) min_interior_d2 = d2;
                }
            }
        }
    }

    if (min_seg_d2 >= grp_cutoff2) return std::sqrt(min_seg_d2) - 2.0 * R_cap_outer;
    double cap_lb = std::sqrt(min_seg_d2) - 2.0 * R_cap_outer;
    if (cap_lb >= skip_sdf_above) return cap_lb;
    if (min_interior_d2 < 0.192 * 0.192 && early_exit_below > -0.006) {
        return std::sqrt(min_interior_d2) - 2.0 * R_tube_nom;
    }

    Mat3 R_inv = R_can.T();
    Vec3 t_inv = R_inv * (t_can * -1.0);

    double min_d = skip_sdf_above + 0.02;
    int active_B[64], n_act_B = 0;
    int active_A[64], n_act_A = 0;
    for (int j = 0; j < n_caps; ++j) {
        if (std::sqrt(min_d2_B[j]) - 2.0 * R_cap_outer < min_d) active_B[n_act_B++] = j;
    }
    for (int i = 0; i < n_caps; ++i) {
        if (std::sqrt(min_d2_A[i]) - 2.0 * R_cap_outer < min_d) active_A[n_act_A++] = i;
    }

    // Pass 1: Stride-8 coarse scan across active buckets for instant collision early-exit!
    for (int bi = 0; bi < n_act_B; ++bi) {
        int j = active_B[bi];
        if (std::sqrt(min_d2_B[j]) - 2.0 * R_cap_outer >= min_d) continue;
        const auto& vec = seg_pts[j];
        for (size_t k = 0; k < vec.size(); k += 8) {
            Vec3 p(vec[k].x, vec[k].y, vec[k].z);
            double db = lookup_sdf(R_can * p + t_can);
            if (db < min_d) {
                min_d = db;
                if (min_d < early_exit_below) return min_d;
            }
        }
    }
    for (int ai = 0; ai < n_act_A; ++ai) {
        int i = active_A[ai];
        if (std::sqrt(min_d2_A[i]) - 2.0 * R_cap_outer >= min_d) continue;
        const auto& vec = seg_pts[i];
        for (size_t k = 0; k < vec.size(); k += 8) {
            Vec3 p(vec[k].x, vec[k].y, vec[k].z);
            double da = lookup_sdf(R_inv * p + t_inv);
            if (da < min_d) {
                min_d = da;
                if (min_d < early_exit_below) return min_d;
            }
        }
    }

    // Pass 2: Full scan of remaining points in buckets whose lower bound < min_d!
    for (int bi = 0; bi < n_act_B; ++bi) {
        int j = active_B[bi];
        if (std::sqrt(min_d2_B[j]) - 2.0 * R_cap_outer >= min_d) continue;
        const auto& vec = seg_pts[j];
        for (size_t k = 0; k < vec.size(); ++k) {
            if ((k & 7) == 0) continue;
            Vec3 p(vec[k].x, vec[k].y, vec[k].z);
            double db = lookup_sdf(R_can * p + t_can);
            if (db < min_d) {
                min_d = db;
                if (min_d < early_exit_below) return min_d;
            }
        }
    }
    for (int ai = 0; ai < n_act_A; ++ai) {
        int i = active_A[ai];
        if (std::sqrt(min_d2_A[i]) - 2.0 * R_cap_outer >= min_d) continue;
        const auto& vec = seg_pts[i];
        for (size_t k = 0; k < vec.size(); ++k) {
            if ((k & 7) == 0) continue;
            Vec3 p(vec[k].x, vec[k].y, vec[k].z);
            double da = lookup_sdf(R_inv * p + t_inv);
            if (da < min_d) {
                min_d = da;
                if (min_d < early_exit_below) return min_d;
            }
        }
    }
    return min_d;
}

